function runChain(
  req: Record<string, unknown>,
  res: MockRes,
  handlers: HandlerLayer[],
): void {
  let i = 0;
  // next is synchronous: each handler is fired as a fire-and-forget Promise,
  // with errors redirected to res._reject so res.promise always settles.
  //
  // Double-next() guard: a buggy middleware that calls next() more than once
  // would normally advance `i` twice, invoking the wrong handler.  We defend
  // against this by capturing the value of `i` that was current when next()
  // was called and only advancing from that slot.  Subsequent calls to the
  // same next() closure are silently ignored (the first call already fired
  // its handler).
  const next = (err?: unknown): void => {
    if (err) {
      res._reject(err instanceof Error ? err : new Error(String(err)));
      return;
    }
    if (i >= handlers.length) return;
    const slot = i++;
    const fn = handlers[slot]!.handle;
    Promise.resolve(
      (fn as (req: unknown, res: unknown, next: unknown) => unknown)(req, res, next),
    ).catch((e: unknown) => res._reject(e));
  };
  next();
}

